interface IMessage{string Read();}
class Plain:IMessage{public string Read()=>"An";}
class Prefix(IMessage inner):IMessage{public string Read()=>"xin chào "+inner.Read();}
class Upper(IMessage inner):IMessage{public string Read()=>inner.Read().ToUpperInvariant();}
class Counted:IMessage{public int Calls;public string Read(){Calls++;return "data";}}
class Cached(IMessage inner):IMessage{private string? value;public string Read()=>value??=inner.Read();}
class Failing:IMessage{public string Read()=>throw new InvalidOperationException();}

